mapper.select:
SELECT STRAIGHT_JOIN dc.id AS id, dc.created_at AS dtsCreated
FROM data_captures dc FORCE INDEX (idx_dc_tenant_cat_created)
INNER JOIN process p ON p.id = dc.process_id
LEFT JOIN  desc_agg ON desc_agg.process_id = p.id
WHERE dc.tenant_id = #{tenantId}
  AND dc.capture_date >= #{dateFrom}
  AND dc.capture_date <= #{dateTo}
  AND dc.category = #{category}

  AND (UPPER(p.code) = UPPER(#{process}) OR CAST(p.id AS CHAR) = #{process})

  AND EXISTS (
      SELECT 1
      FROM data_capture_line dl
      INNER JOIN currency c ON c.id = dl.currency_id AND c.tenant_id = dl.tenant_id
      INNER JOIN account a ON a.id = dl.account_id
      WHERE dl.capture_id = dc.id AND dl.tenant_id = dc.tenant_id

      LIMIT 1
  )

  AND (dc.created_at < #{cursorCreatedAt}
       OR (dc.created_at = #{cursorCreatedAt} AND dc.id < #{cursorId}))

ORDER BY dc.created_at DESC, dc.id DESC
LIMIT #{limit}

SELECT dl.id AS id, dl.created_at AS dtsCreated, p.code AS process, AS idProduct, a.account_id AS account, COALESCE(desc_agg.description_names, ) AS description, dc.remark AS remark, dl.source_percent AS percent, UPPER(c.code) AS currency, dl.rate_expression AS rate, CASE WHEN dl.processed_amount >= 0 THEN dl.processed_amount ELSE NULL END AS cr, CASE WHEN dl.processed_amount < 0 THEN ABS(dl.processed_amount) ELSE NULL END AS dr, dc.created_by AS createdBy, FALSE AS deleted, NULL AS deletedBy, NULL AS deletedAt FROM data_capture_line dl INNER JOIN data_captures dc ON dc.id = dl.capture_id AND dc.tenant_id = dl.tenant_id INNER JOIN process p ON p.id = dc.process_id INNER JOIN currency c ON c.id = dl.currency_id AND c.tenant_id = dl.tenant_id INNER JOIN account a ON a.id = dl.account_id LEFT JOIN desc_agg ON desc_agg.process_id = p.id WHERE dl.tenant_id = #{tenantId} AND dl.capture_id IN
#{captureId}
ORDER BY dc.created_at DESC, dc.id DESC, dl.id DESC

