mapper.sql:
FROM data_capture_formula f INNER JOIN process p ON p.id = f.process_id AND p.tenant_id = f.tenant_id LEFT JOIN account a ON a.id = f.account_id LEFT JOIN currency c ON c.id = f.currency_id AND c.tenant_id = f.tenant_id WHERE f.tenant_id = #{tenantId} AND p.category = #{category}
AND (UPPER(p.code) = UPPER(#{process}) OR CAST(p.id AS CHAR) = #{process})
AND ( UPPER(f.id_product) LIKE CONCAT('%', UPPER(#{q}), '%') OR UPPER(COALESCE(a.account_id, '')) LIKE CONCAT('%', UPPER(#{q}), '%') OR UPPER(COALESCE(f.description, '')) LIKE CONCAT('%', UPPER(#{q}), '%') OR UPPER(COALESCE(f.formula, '')) LIKE CONCAT('%', UPPER(#{q}), '%') OR UPPER(COALESCE(f.created_by, '')) LIKE CONCAT('%', UPPER(#{q}), '%') )

mapper.update:
UPDATE data_capture_formula
SET source_percent = #{sourcePercent},
    input_method = #{inputMethod},
    formula = #{formula},
    description = #{description},
    account_id = #{accountId},
    updated_by = #{updatedBy}
WHERE id = #{id}
  AND tenant_id = #{tenantId}

